private val inLine = ArrayList<String>()
private var index = 0
private var max = 0

private fun hasNext(): Boolean {
    return index < max
}

private fun next(): String {
    if (hasNext()) {
        return inLine[index++]
    } else {
        throw ArrayIndexOutOfBoundsException("There is no more input")
    }
}

private fun nextInt(): Int {
    return myconv(next(), 1) as Int
}

private fun nextStrArray(): Array<String> {
    @Suppress("UNCHECKED_CAST")
    return myconv(next(), 2) as Array<String>
}

private fun nextIntArray(): IntArray {
    return myconv(next(), 4) as IntArray
}

private fun nextCharArray(): Array<String> {
    @Suppress("UNCHECKED_CAST")
    return myconv(next(), 6) as Array<String>
}

private fun myout(s: Any?) {
    println(s)
}

private fun myerr(s: Any?) {
    System.err.println("debug:" + s)
}

//param "no" is
//unknown or outlier : return i. 1: parseInt.
//2: split space. 4: split space and parseInt.
//6: split 1 character. 7: split 1 character and parseInt.
//8: join space. 9: join nextline. 0: join no character.
private fun myconv(i: Any?, no: Int): Any? {
    try {
        when (no) {
            1 -> return (i as String).toInt()
            2 -> return (i as String).split(" ").toTypedArray()
            4 -> return (i as String).split(" ").map { it.toInt() }.toIntArray()
            6 -> return (i as String).map { it.toString() }.toTypedArray()
            7 -> return (i as String).map { it.toString().toInt() }.toIntArray()
            8 -> return (i as List<*>).joinToString(" ")
            9 -> return (i as List<*>).joinToString("\n")
            0 -> return (i as List<*>).joinToString("")
            else -> return i
        }
    } catch (e: Exception) {
        return i
    }
}

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    var line = br.readLine()
    while (line != null) {
        inLine.add(line)
        line = br.readLine()
    }
    max = inLine.size
    System.err.println("\n↑入力 ↓出力")
    Main()
}

//Don't have to see. end------------------------------------------
fun Main() {
    val N = nextInt()
    val s = next().split("W")
    val output = ArrayList<Int>()
    for (i in s.indices) {
        if (s[i] != "") {
            output.add(s[i].length)
        }
    }
    myout(output.size)
    myout(myconv(output, 8))
}
